// Code generated by tests/gen-port.sh from cgo/data.go. DO NOT EDIT.

// fill, verify, delete and dump of the deterministic data set, and drop of
// a whole DB (rlmdb rust/interop/c/cpeer_data.c).
//
// fill and delete write; verify proves that a DB holds exactly the data set
// (as modified by a prior delete), using every read path a peer must get
// right: point lookups, full cursor walks in both directions, duplicate
// navigation, GetMultiple for DUPFIXED, and the DB statistics.

package peer

import (
	"bytes"
	"encoding/hex"
	"fmt"
	"os"

	lmdb "github.com/PowerDNS/lmdb-go/lmdb"
)

func printDBStat(what string, txn *lmdb.Txn, dbi lmdb.DBI, ds *dataset, txns int) {
	st, err := txn.Stat(dbi)
	check(err, "mdb_stat")
	printf("%s db=%s keys=%d entries=%d txns=%d psize=%d depth=%d"+
		" branch_pages=%d leaf_pages=%d overflow_pages=%d\n",
		what, dbLabel(ds.db), ds.count, st.Entries, txns, st.PSize,
		st.Depth, st.BranchPages, st.LeafPages, st.OverflowPages)
}

// ---- fill ----

// putItem puts one item with mdb_put (optionally MDB_RESERVE, which
// lmdb-go offers as Txn.PutReserve).
func putItem(txn *lmdb.Txn, dbi lmdb.DBI, o *opts, i, d uint32, key, vbuf []byte) {
	ds := &o.ds
	n := ds.vlen(i, d)
	if o.reserve {
		// MDB_RESERVE: LMDB hands out the space, we write the value into it.
		v, err := txn.PutReserve(dbi, key, n, 0)
		check(err, "mdb_put(MDB_RESERVE)")
		ds.value(i, d, v)
		return
	}
	ds.value(i, d, vbuf[:n])
	check(txn.Put(dbi, key, vbuf[:n], 0), "mdb_put")
}

func cmdFill(o *opts) int {
	parseDatasetArgs(o, 1)
	ds := &o.ds
	if o.reserve && ds.dbflags&lmdb.DupSort != 0 {
		die(exitUsage, "--reserve cannot be used with DUPSORT")
	}
	env := openEnv(o, 0)
	vbuf := make([]byte, ds.maxValueSize())
	txns := 1
	n := uint32(0)
	txn := beginWrite(env)
	dbi, err := openDB(txn, ds.db, ds.dbflags|lmdb.Create)
	check(err, "mdb_dbi_open")

	if o.appendMode {
		// Insert in comparator order with MDB_APPEND (new key) and
		// MDB_APPENDDUP (further values of the same key) via a cursor.
		// The DB must not already hold keys sorting after ours.
		m := buildModel(ds)
		cur, err := txn.OpenCursor(dbi)
		check(err, "mdb_cursor_open")
		for k, it := range m.items {
			for j, v := range it.vals {
				flag := uint(lmdb.AppendDup)
				if j == 0 {
					flag = lmdb.Append
				}
				check(cur.Put(it.key, v, flag), "mdb_cursor_put(&it->key, &it->vals[j], j == 0 ? MDB_APPEND : MDB_APPENDDUP)")
			}
			n++
			if o.perTxn != 0 && n%o.perTxn == 0 && k+1 < len(m.items) {
				cur.Close()
				commitWrite(txn)
				txn = beginWrite(env)
				txns++
				cur, err = txn.OpenCursor(dbi)
				check(err, "mdb_cursor_open")
			}
		}
		cur.Close()
	} else {
		// Insert in index order, which is random order for the comparator.
		kbuf := make([]byte, 0, 24)
		for i := uint32(0); i < ds.count; i++ {
			key := ds.key(i, kbuf[:0])
			for d := uint32(0); d < ds.ndups(i); d++ {
				if ds.present(i, d) {
					putItem(txn, dbi, o, i, d, key, vbuf)
				}
			}
			n++
			if o.perTxn != 0 && n%o.perTxn == 0 && i+1 < ds.count {
				commitWrite(txn)
				txn = beginWrite(env)
				txns++
			}
		}
	}
	printDBStat("filled", txn, dbi, ds, txns)
	commitWrite(txn)
	env.Close()
	return 0
}

// ---- verify ----

// mismatch reports a verify failure on stderr and returns exitMismatch.
func mismatch(db string, format string, a ...any) int {
	stdout.Flush()
	fmt.Fprintf(os.Stderr, "gopeer: verify db=%s: %s\n", dbLabel(db), fmt.Sprintf(format, a...))
	return exitMismatch
}

// shortHex is up to 40 bytes of a value as hex, for error messages.
func shortHex(v []byte) string {
	if len(v) > 40 {
		return hex.EncodeToString(v[:40]) + "..."
	}
	return hex.EncodeToString(v)
}

// checkWalk walks the whole DB with step (Next or Prev) and compares it
// with the flattened model: entry (k, j) is value j of model item k.
func checkWalk(cur *lmdb.Cursor, ds *dataset, m *model, first, step uint) int {
	dir := "forward"
	if step != lmdb.Next {
		dir = "backward"
	}
	seen, k, j := 0, 0, 0
	if step == lmdb.Prev && len(m.items) > 0 {
		k = len(m.items) - 1
		j = len(m.items[k].vals) - 1
	}
	key, data, err := cur.Get(nil, nil, first)
	for ; err == nil; key, data, err = cur.Get(nil, nil, step) {
		if seen >= m.nentries {
			return mismatch(ds.db, "%s walk: extra item key=%s", dir, shortHex(key))
		}
		seen++
		it := &m.items[k]
		if !bytes.Equal(key, it.key) || !bytes.Equal(data, it.vals[j]) {
			return mismatch(ds.db, "%s walk: entry %d is %s=%s, expected %s=%s (i=%d)",
				dir, seen-1, shortHex(key), shortHex(data),
				shortHex(it.key), shortHex(it.vals[j]), it.i)
		}
		// advance (k, j) in walk direction
		if step == lmdb.Next {
			if j++; j == len(it.vals) {
				k++
				j = 0
			}
		} else if j > 0 {
			j--
		} else if k > 0 {
			k--
			j = len(m.items[k].vals) - 1
		}
	}
	if !lmdb.IsNotFound(err) {
		check(err, "mdb_cursor_get(walk)")
	}
	if seen != m.nentries {
		return mismatch(ds.db, "%s walk saw %d entries, expected %d", dir, seen, m.nentries)
	}
	return 0
}

// checkDups checks the duplicate navigation: count, GET_BOTH, NEXT_NODUP,
// FIRST_DUP/LAST_DUP and, for DUPFIXED, GET_MULTIPLE/NEXT_MULTIPLE.
func checkDups(cur *lmdb.Cursor, ds *dataset, m *model) int {
	for k := range m.items {
		it := &m.items[k]
		_, _, err := cur.Get(it.key, nil, lmdb.Set)
		check(err, "mdb_cursor_get(MDB_SET)")
		count, err := cur.Count()
		check(err, "mdb_cursor_count")
		if count != uint64(len(it.vals)) {
			return mismatch(ds.db, "key i=%d has %d values, expected %d", it.i, count, len(it.vals))
		}
		_, data, err := cur.Get(nil, nil, lmdb.LastDup)
		check(err, "mdb_cursor_get(MDB_LAST_DUP)")
		if !bytes.Equal(data, it.vals[len(it.vals)-1]) {
			return mismatch(ds.db, "MDB_LAST_DUP of i=%d is %s", it.i, shortHex(data))
		}
		_, data, err = cur.Get(nil, nil, lmdb.FirstDup)
		check(err, "mdb_cursor_get(MDB_FIRST_DUP)")
		if !bytes.Equal(data, it.vals[0]) {
			return mismatch(ds.db, "MDB_FIRST_DUP of i=%d is %s", it.i, shortHex(data))
		}
		for j, v := range it.vals {
			_, d2, err := cur.Get(it.key, v, lmdb.GetBoth)
			if lmdb.IsNotFound(err) {
				return mismatch(ds.db, "MDB_GET_BOTH: value %d of i=%d not found", j, it.i)
			}
			check(err, "mdb_cursor_get(MDB_GET_BOTH)")
			if !bytes.Equal(d2, v) {
				return mismatch(ds.db, "MDB_GET_BOTH of i=%d returned %s", it.i, shortHex(d2))
			}
		}
		if ds.dbflags&lmdb.DupFixed != 0 {
			// GET_MULTIPLE returns up to a page of packed values, and
			// NEXT_MULTIPLE the following pages, of the current key.
			_, setData, err := cur.Get(it.key, nil, lmdb.Set)
			check(err, "mdb_cursor_get(MDB_SET)")
			got := 0
			vs := int(ds.valsize)
			_, data, err := cur.Get(nil, nil, lmdb.GetMultiple)
			if err == nil && len(data) == 0 {
				// A key with one value has no sub-DB or sub-page: C's
				// mdb_cursor_get(MDB_GET_MULTIPLE) then succeeds without
				// touching *data, which still holds MDB_SET's value.
				// lmdb-go clears its MDB_val after every call and returns
				// an empty slice; use MDB_SET's value as C's caller sees.
				data = setData
			}
			for ; err == nil; _, data, err = cur.Get(nil, nil, lmdb.NextMultiple) {
				if len(data)%vs != 0 {
					return mismatch(ds.db, "GET_MULTIPLE size %d not a multiple of %d", len(data), vs)
				}
				for off := 0; off < len(data); off, got = off+vs, got+1 {
					if got >= len(it.vals) || !bytes.Equal(data[off:off+vs], it.vals[got]) {
						return mismatch(ds.db, "GET_MULTIPLE value %d of i=%d differs", got, it.i)
					}
				}
			}
			if !lmdb.IsNotFound(err) {
				check(err, "mdb_cursor_get(MDB_NEXT_MULTIPLE)")
			}
			if got != len(it.vals) {
				return mismatch(ds.db, "GET_MULTIPLE saw %d values of i=%d, expected %d",
					got, it.i, len(it.vals))
			}
		}
	}
	nkeys := 0
	_, _, err := cur.Get(nil, nil, lmdb.First)
	for ; err == nil; _, _, err = cur.Get(nil, nil, lmdb.NextNoDup) {
		nkeys++
	}
	if !lmdb.IsNotFound(err) {
		check(err, "mdb_cursor_get(MDB_NEXT_NODUP)")
	}
	if nkeys != len(m.items) {
		return mismatch(ds.db, "MDB_NEXT_NODUP saw %d keys, expected %d", nkeys, len(m.items))
	}
	return 0
}

// verifyInTxn verifies the data set ds inside an existing transaction
// (shared by verify and hold-reader). Returns 0, or exitMismatch after
// printing the first difference to stderr.
func verifyInTxn(txn *lmdb.Txn, ds *dataset, quiet bool) int {
	dbi, err := openDB(txn, ds.db, 0)
	if lmdb.IsNotFound(err) {
		return mismatch(ds.db, "database not found")
	}
	check(err, "mdb_dbi_open")
	flags, err := txn.Flags(dbi)
	check(err, "mdb_dbi_flags")
	if flags != ds.dbflags {
		return mismatch(ds.db, "DB flags are 0x%x, expected 0x%x", flags, ds.dbflags)
	}

	m := buildModel(ds)
	st, err := txn.Stat(dbi)
	check(err, "mdb_stat")
	if st.Entries != uint64(m.nentries) {
		return mismatch(ds.db, "mdb_stat entries %d, expected %d", st.Entries, m.nentries)
	}

	// Point lookups: present keys return their first (smallest) value.
	for k := range m.items {
		data, err := txn.Get(dbi, m.items[k].key)
		if lmdb.IsNotFound(err) {
			return mismatch(ds.db, "mdb_get: key i=%d not found", m.items[k].i)
		}
		check(err, "mdb_get")
		if !bytes.Equal(data, m.items[k].vals[0]) {
			return mismatch(ds.db, "mdb_get: key i=%d has value %s", m.items[k].i, shortHex(data))
		}
	}
	// Deleted keys are gone.
	kbuf := make([]byte, 0, 24)
	for _, i := range m.absent {
		_, err := txn.Get(dbi, ds.key(i, kbuf[:0]))
		if !lmdb.IsNotFound(err) {
			return mismatch(ds.db, "mdb_get: deleted key i=%d is present (rc=%s)", i, rcText(err))
		}
	}

	cur, err := txn.OpenCursor(dbi)
	check(err, "mdb_cursor_open")
	defer cur.Close()
	rc := checkWalk(cur, ds, m, lmdb.First, lmdb.Next)
	if rc == 0 {
		rc = checkWalk(cur, ds, m, lmdb.Last, lmdb.Prev)
	}
	if rc == 0 && ds.dbflags&lmdb.DupSort != 0 {
		rc = checkDups(cur, ds, m)
	}
	// MDB_SET_RANGE on an existing key lands on that key.
	for k := 0; rc == 0 && k < len(m.items); k += 7 {
		key, _, err := cur.Get(m.items[k].key, nil, lmdb.SetRange)
		check(err, "mdb_cursor_get(MDB_SET_RANGE)")
		if !bytes.Equal(key, m.items[k].key) {
			rc = mismatch(ds.db, "MDB_SET_RANGE(i=%d) landed on %s", m.items[k].i, shortHex(key))
		}
	}
	if rc == 0 && !quiet {
		printf("verified db=%s keys=%d entries=%d absent=%d\n",
			dbLabel(ds.db), len(m.items), m.nentries, len(m.absent))
	}
	return rc
}

// rcText is C's "rc=%d" of an error: 0 for none.
func rcText(err error) string {
	if err == nil {
		return "0"
	}
	return errText(err)
}

func cmdVerify(o *opts) int {
	parseDatasetArgs(o, 1)
	env := openEnv(o, lmdb.Readonly)
	txn := beginRead(env)
	rc := verifyInTxn(txn, &o.ds, false)
	txn.Abort()
	env.Close()
	return rc
}

// ---- delete ----

// delKeyNoted is set once the NOT-IMPLEMENTED note of delKey was printed.
var delKeyNoted bool

// delKey is mdb_del(txn, dbi, key, NULL): delete key with all its values.
// lmdb-go's Txn.Del always passes a value (an empty one for nil), so on a
// DUPSORT DB it cannot express mdb_del(key, NULL): C LMDB looks for the
// empty value (MDB_GET_BOTH) and fails with MDB_NOTFOUND or, for a key
// with a sub-page or sub-DB, MDB_BAD_VALSIZE. There the key is deleted as
// mdb_del0 does internally, with MDB_SET and mdb_cursor_del(MDB_NODUPDATA),
// and a note says so once on stderr. (The tree changes are the same.)
func delKey(txn *lmdb.Txn, dbi lmdb.DBI, cur *lmdb.Cursor, key []byte, dupsort bool) error {
	if !dupsort {
		return txn.Del(dbi, key, nil)
	}
	if !delKeyNoted {
		delKeyNoted = true
		stdout.Flush()
		fmt.Fprintln(os.Stderr, "gopeer: NOT-IMPLEMENTED mdb_del(key, NULL) on a DUPSORT DB:"+
			" lmdb-go's Txn.Del(dbi, key, nil) passes an empty value;"+
			" deleted with MDB_SET + mdb_cursor_del(MDB_NODUPDATA) instead")
	}
	if _, _, err := cur.Get(key, nil, lmdb.Set); err != nil {
		return err
	}
	return cur.Del(lmdb.NoDupData)
}

func cmdDelete(o *opts) int {
	parseDatasetArgs(o, 1)
	ds := &o.ds
	every := o.every
	if every == 0 {
		die(exitUsage, "--every must be > 0")
	}
	env := openEnv(o, 0)
	vbuf := make([]byte, ds.maxValueSize())
	kbuf := make([]byte, 0, 24)
	dupsort := ds.dbflags&lmdb.DupSort != 0
	keys, entries, txns := 0, 0, 1
	n := uint32(0)
	txn := beginWrite(env)
	dbi, err := openDB(txn, ds.db, 0)
	check(err, "mdb_dbi_open")
	cur, err := txn.OpenCursor(dbi)
	check(err, "mdb_cursor_open")

	for i := uint32(0); i < ds.count; i++ {
		key := ds.key(i, kbuf[:0])
		nd := ds.ndups(i)
		left := 0
		for d := uint32(0); d < nd; d++ {
			if ds.present(i, d) {
				left++
			}
		}
		if left == 0 {
			continue // already deleted by a previous delete
		}
		if deleteKey(every, i) {
			// Alternate between mdb_del() and a cursor delete of the
			// whole key (all its values).
			var err error
			if (i/every)%2 == 0 {
				err = delKey(txn, dbi, cur, key, dupsort)
			} else {
				_, _, err = cur.Get(key, nil, lmdb.Set)
				if err == nil {
					flags := uint(0)
					if dupsort {
						flags = lmdb.NoDupData
					}
					err = cur.Del(flags)
				}
			}
			if lmdb.IsNotFound(err) {
				die(exitMismatch, "delete: key i=%d not found", i)
			}
			check(err, "delete key")
			keys++
			entries += left
		} else {
			for d := uint32(0); d < nd; d++ {
				if !ds.present(i, d) || !ds.deleteDup(every, i, d) {
					continue
				}
				data := vbuf[:ds.vlen(i, d)]
				ds.value(i, d, data)
				// Alternate between mdb_del(key, data) and a cursor
				// positioned with MDB_GET_BOTH.
				var err error
				if (d/2)%2 == 0 {
					err = txn.Del(dbi, key, data)
				} else {
					_, _, err = cur.Get(key, data, lmdb.GetBoth)
					if err == nil {
						err = cur.Del(0)
					}
				}
				if lmdb.IsNotFound(err) {
					die(exitMismatch, "delete: value %d of key i=%d not found", d, i)
				}
				check(err, "delete value")
				entries++
				if left--; left == 0 {
					keys++
				}
			}
		}
		n++
		if o.perTxn != 0 && n%o.perTxn == 0 && i+1 < ds.count {
			cur.Close()
			commitWrite(txn)
			txn = beginWrite(env)
			txns++
			cur, err = txn.OpenCursor(dbi)
			check(err, "mdb_cursor_open")
		}
	}
	cur.Close()
	printf("deleted db=%s keys=%d entries=%d txns=%d\n", dbLabel(ds.db), keys, entries, txns)
	commitWrite(txn)
	env.Close()
	return 0
}

// ---- drop ----

// cmdDrop is mdb_drop(): empty the DB, or with --delete delete it from the
// environment (the main DB can only be emptied). Prints what it held.
func cmdDrop(o *opts) int {
	db := o.dbArg(1)
	env := openEnv(o, 0)
	txn := beginWrite(env)
	dbi, err := openDB(txn, db, 0)
	if lmdb.IsNotFound(err) {
		die(exitMismatch, "drop: database %s not found", dbLabel(db))
	}
	check(err, "mdb_dbi_open")
	st, err := txn.Stat(dbi)
	check(err, "mdb_stat")
	check(txn.Drop(dbi, o.del), "mdb_drop")
	del := 0
	if o.del {
		del = 1
	}
	printf("dropped db=%s delete=%d entries=%d pages=%d\n", dbLabel(db), del,
		st.Entries, st.BranchPages+st.LeafPages+st.OverflowPages)
	commitWrite(txn)
	env.Close()
	return 0
}

// ---- dump ----

// isSubDB tells whether key of the main DB is the name of a named DB (as
// mdb_stat -a decides; in LMDB 1.0 the key is the name with its NUL).
func isSubDB(txn *lmdb.Txn, v10 bool, key []byte) (string, bool) {
	name, ok := subDBName(v10, key)
	if !ok {
		return "", false
	}
	if _, err := txn.OpenDBI(name, 0); err != nil {
		return "", false
	}
	return name, true
}

// dumpDB prints "db=<label>" then one "<hexkey>=<hexvalue>" line per item,
// in cursor order. Named-DB records of the main DB print as "<hexkey>=@db"
// because their value (an MDB_db with page numbers) differs between
// copies. Returns the names of those DBs.
func dumpDB(txn *lmdb.Txn, v10 bool, db string) []string {
	dbi, err := openDB(txn, db, 0)
	if lmdb.IsNotFound(err) {
		die(exitMismatch, "dump: database %s not found", dbLabel(db))
	}
	check(err, "mdb_dbi_open")
	printf("db=%s\n", dbLabel(db))
	cur, err := txn.OpenCursor(dbi)
	check(err, "mdb_cursor_open")
	var names []string
	var line []byte
	key, data, err := cur.Get(nil, nil, lmdb.Next)
	for ; err == nil; key, data, err = cur.Get(nil, nil, lmdb.Next) {
		line = hex.AppendEncode(line[:0], key)
		name, sub := "", false
		if db == "" {
			name, sub = isSubDB(txn, v10, key)
		}
		if sub {
			names = append(names, name)
			line = append(line, "=@db\n"...)
		} else {
			line = append(line, '=')
			line = hex.AppendEncode(line, data)
			line = append(line, '\n')
		}
		stdout.Write(line)
	}
	stdout.Flush()
	if !lmdb.IsNotFound(err) {
		check(err, "mdb_cursor_get")
	}
	cur.Close()
	return names
}

func cmdDump(o *opts) int {
	if o.all == (len(o.pos) == 2) {
		die(exitUsage, "usage: gopeer dump <env> <db|-> | gopeer dump <env> --all")
	}
	env := openEnv(o, lmdb.Readonly)
	v10 := envIs10(env)
	txn := beginRead(env)
	if o.all {
		for _, name := range dumpDB(txn, v10, "") {
			dumpDB(txn, v10, name)
		}
	} else {
		dumpDB(txn, v10, o.dbArg(1))
	}
	txn.Abort()
	env.Close()
	return 0
}
